import { BINARY, NODE_TYPES } from "./format.js";

const TYPE_TAGS = new Map(NODE_TYPES.map((t, i) => [t, i]));
const encoder = new TextEncoder();

class Writer {
    constructor(size = 4096) {
        this.view = new DataView(new ArrayBuffer(size));
        this.bytes = new Uint8Array(this.view.buffer);
        this.length = 0;
    }

    reserve(n) {
        if (this.length + n <= this.bytes.length) {
            return;
        }
        let size = this.bytes.length * 2;
        while (size < this.length + n) {
            size *= 2;
        }
        const next = new Uint8Array(size);
        next.set(this.bytes);
        this.bytes = next;
        this.view = new DataView(next.buffer);
    }

    u8(v) {
        this.reserve(1);
        this.view.setUint8(this.length++, v);
    }

    u32(v) {
        this.reserve(4);
        this.view.setUint32(this.length, v, true);
        this.length += 4;
    }

    f64(v) {
        this.reserve(8);
        this.view.setFloat64(this.length, v, true);
        this.length += 8;
    }

    raw(bytes) {
        this.reserve(bytes.length);
        this.bytes.set(bytes, this.length);
        this.length += bytes.length;
    }
}

/**
 * Encodes a normalized tree into the binary wire format: a 20 byte header
 * (magic, version, seq, node count, string table offset), preorder node
 * records, then the deduped UTF-8 string table. `utf8Cache` is an optional
 * Map<string, Uint8Array> that lets callers skip re-encoding known strings.
 */
export const encodeTree = (tree, seq, utf8Cache = null) => {
    const w = new Writer();
    const strings = [];
    const stringIndex = new Map();
    let nodeCount = 0;

    const ref = (s) => {
        let i = stringIndex.get(s);
        if (i === undefined) {
            i = strings.length;
            stringIndex.set(s, i);
            strings.push(s);
        }
        return i;
    };

    const writeValue = (v) => {
        if (v === null || v === undefined) {
            w.u8(BINARY.VALUE_NULL);
        } else if (typeof v === "boolean") {
            w.u8(v ? BINARY.VALUE_TRUE : BINARY.VALUE_FALSE);
        } else if (typeof v === "number") {
            if (Number.isInteger(v) && v >= 0 && v <= 0xffffffff && !Object.is(v, -0)) {
                w.u8(BINARY.VALUE_UINT32);
                w.u32(v);
            } else {
                w.u8(BINARY.VALUE_FLOAT64);
                w.f64(v);
            }
        } else if (typeof v === "string") {
            w.u8(BINARY.VALUE_STRING);
            w.u32(ref(v));
        } else if (Array.isArray(v)) {
            w.u8(BINARY.VALUE_ARRAY);
            w.u32(v.length);
            for (const item of v) {
                writeValue(item);
            }
        } else {
            const keys = Object.keys(v);
            w.u8(BINARY.VALUE_OBJECT);
            w.u32(keys.length);
            for (const key of keys) {
                w.u32(ref(key));
                writeValue(v[key]);
            }
        }
    };

    const writeNode = (node) => {
        nodeCount++;
        if (typeof node === "string") {
            w.u8(BINARY.NODE_TEXT);
            w.u32(ref(node));
            return;
        }
        const tag = TYPE_TAGS.get(node.type);
        if (tag === undefined) {
            throw new Error(`cannot encode node type ${node.type}`);
        }
        w.u8(BINARY.NODE_ELEMENT);
        w.u8(tag);
        w.u32(node.children.length);
        writeValue(node.props);
        for (const child of node.children) {
            writeNode(child);
        }
    };

    w.length = BINARY.HEADER_BYTES;
    writeNode(tree);

    const tableOffset = w.length;
    w.u32(strings.length);
    for (const s of strings) {
        let bytes = utf8Cache?.get(s);
        if (!bytes) {
            bytes = encoder.encode(s);
            utf8Cache?.set(s, bytes);
        }
        w.u32(bytes.length);
        w.raw(bytes);
    }

    w.view.setUint32(0, BINARY.MAGIC, true);
    w.view.setUint32(4, BINARY.VERSION, true);
    w.view.setUint32(8, seq, true);
    w.view.setUint32(12, nodeCount, true);
    w.view.setUint32(16, tableOffset, true);
    return w.bytes.buffer.slice(0, w.length);
};
