import { encodeTree } from "./encode.js";
import { evaluateRevision } from "./facade.js";

// Per-thread cache of UTF-8 encoded strings, reused across revisions of a reply.
const threads = new Map();

const cacheFor = (threadId) => {
    let cache = threads.get(threadId);
    if (!cache) {
        cache = new Map();
        threads.set(threadId, cache);
    }
    return cache;
};

self.onmessage = ({ data }) => {
    if (data.type === "reset") {
        threads.clear();
        return;
    }
    if (data.type !== "revision") {
        return;
    }
    const seq = data.revision?.seq ?? -1;
    try {
        const start = performance.now();
        const tree = evaluateRevision(data.revision);
        const compileMs = performance.now() - start;
        const buffer = encodeTree(tree, seq, cacheFor(data.threadId ?? "default"));
        self.postMessage({ type: "tree", seq, buffer, compileMs }, [buffer]);
    } catch (error) {
        self.postMessage({ type: "error", seq, message: String(error?.message ?? error) });
    }
};
