import {
    COMPONENT_TYPES,
    FIXED_NOW,
    LOCALE,
    PROGRAM_PARAMS,
    PROGRAM_PREAMBLE,
    ROOT_TYPE,
    WIDGET_TYPE,
} from "./format.js";

const ALLOWED = new Set(COMPONENT_TYPES);
const FRAGMENT = Symbol("fragment");

const flatten = (children, widgets, out) => {
    for (const child of children) {
        if (child === null || child === undefined || child === false || child === true) {
            continue;
        }
        if (Array.isArray(child)) {
            flatten(child, widgets, out);
        } else if (typeof child === "string") {
            out.push(child);
        } else if (typeof child === "number") {
            out.push(String(child));
        } else if (child.type === FRAGMENT) {
            flatten(child.children, widgets, out);
        } else if (child.type === WIDGET_TYPE) {
            const widget = widgets.get(child.props.id);
            if (!widget) {
                throw new Error(`unknown widget ${child.props.id}`);
            }
            out.push({
                type: WIDGET_TYPE,
                props: { id: widget.id, kind: widget.kind, lang: widget.lang, source: widget.source, complete: widget.complete },
                children: [],
            });
        } else {
            out.push({ type: child.type, props: child.props ?? {}, children: flatten(child.children, widgets, []) });
        }
    }
    return out;
};

const createFacade = (revision) => {
    const widgets = new Map(revision.widgets.map((w) => [w.id, w]));
    let mounted = null;
    const ui = {
        Fragment: FRAGMENT,
        h(type, props, ...children) {
            if (type !== FRAGMENT && !ALLOWED.has(type)) {
                throw new Error(`unknown component type ${String(type)}`);
            }
            return { type, props, children };
        },
        mount(render) {
            mounted = render();
            return mounted;
        },
        strings: () => revision.strings,
        widget: (id) => ({ type: WIDGET_TYPE, props: { id }, children: [] }),
    };
    return { ui, widgets, getRoot: () => mounted };
};

const DateStub = Object.freeze({ now: () => FIXED_NOW });
const ENV = Object.freeze({ locale: LOCALE, now: FIXED_NOW });

/**
 * Compiles and runs a revision's program against the facade API and returns the
 * normalized tree: { type: "root", props: {}, children } with element nodes
 * { type, props, children }, text as strings and widgets resolved from revision.widgets.
 */
export const evaluateRevision = (revision) => {
    const { ui, widgets } = createFacade(revision);
    const run = new Function(...PROGRAM_PARAMS, PROGRAM_PREAMBLE + revision.program);
    const result = run(ui, ENV, DateStub);
    if (result === undefined || result === null) {
        throw new Error("program did not mount a tree");
    }
    return { type: ROOT_TYPE, props: {}, children: flatten([result], widgets, []) };
};
